                            function_call: Some(GeminiFunctionCall {
                                name: name.clone(),
                                args: ToolCall::input_as_object(input),
                                id: Some(id.clone()),
                            }),
                            thought_signature: signature,
                            ..Default::default()
                        });
                    }
