                                data: data.clone(),
                            }),
                            ..Default::default()
                        });
                    }
                    ContentBlock::OpenAICompaction { .. } => {}
                }
            }
            if parts.is_empty() {
                None
            } else {
                Some(GeminiContent {
                    role: role.to_string(),
                    parts,
                })
            }
        })

